import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"天雷无妄","description":"周易折中 - 天雷无妄","frontmatter":{"title":"天雷无妄","description":"周易折中 - 天雷无妄"},"headers":[],"relativePath":"zh/classics/zhezhong/031.md","filePath":"zh/classics/zhezhong/031.md"}'),h={name:"zh/classics/zhezhong/031.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="天雷无妄" tabindex="-1">天雷无妄 <a class="header-anchor" href="#天雷无妄" aria-label="Permalink to “天雷无妄”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>无妄序卦：复则不妄矣，故受之以无妄。复者，反于道也；既复于道，则合正理而无妄，故复之后受之以无妄也。为卦，干上震下，震动也；动以天为无妄，动以人欲则妄矣。无妄之义大矣哉！</p><p>无妄：元亨利贞，其匪正有眚，不利有攸往。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>无妄，实理自然之谓。《史记》作“无望”，谓无所期望而有得焉者，其义亦通。为卦自讼而变，九自二来而居于初，又为震主动而不妄者也，故为无妄。又二体震动而乾健，九五刚中而应六二，故其占大亨而利于正。若其不正，则有眚而不利有所往也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>无妄者，至诚也。至诚者，天之道也。天之化育万物，生生不穷，各正其性命，乃无妄也。人能合无妄之道，则所谓与天地合其德也。无妄有大亨之理，君子行无妄之道，则可以致大亨矣。无妄，天之道也；卦言人由无妄之道也。利贞，法无妄之道，利在贞正。失贞正则妄也，虽无邪心，苟不合正理，则妄也，乃邪心也。故有匪正，则为过眚。既已无妄，不宜有往，往则妄也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云：无妄一卦，虽云祸福之来也无常，然自家所守者不可不利于正，不可以彼之无常而吾之所守亦为之无常也。故曰“无妄，元亨利贞，其匪正有眚”。 问 ：虽无邪心，苟不合正理，则妄也。既无邪，何以不合正？ 曰：有人自是其心，全无邪而却不合于正理，如贤者过之，其心岂曾有邪，却不合正理。佛氏亦岂有邪心者。</p></li><li><p>问 ：虽无邪心，苟不合正理，则妄也。既无邪，何以不合正？ 曰：有人自是其心，全无邪而却不合于正理，如贤者过之，其心岂曾有邪，却不合正理。佛氏亦岂有邪心者。</p></li><li><p>丘氏富国曰：惟其无妄，所以无望也。若其处心未免于妄，则无道以致福，而妄欲徼福，非所谓无望之福；有过以召灾，而妄欲免灾，非所谓无望之灾。此皆未免容心于祸福间，非所谓无妄也。若真实无妄之人，则纯乎正理，祸福一付之天，而无苟得幸免之心也。</p></li><li><p>胡氏炳文曰：朱子解《中庸》“诚”字，以为“真实无妄”之谓；此解无妄，则以为“实理自然”之谓。自然二字，已兼无所期望之意矣。</p></li><li><p>胡氏居仁曰：无妄，诚也。诚，天理之实也。圣人只是循其实理之自然，无一毫私意造为。故出乎实理无妄之外，则为过眚。循此实理无妄而行之，则吉无不利。不幸而灾疾之来，亦守此无妄之实理而不足忧。卦辞、爻辞皆此意。</p></li></ul><p>象曰：天下雷行，物与无妄；先王以茂对时，育万物</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>天下雷行，震动发生，万物各得其性命，是物物而与之以无妄也。先王法此以对时育物，因其所性而不为私焉。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>雷行于天下，阴阳交和相薄而成声，于是惊蛰藏振，萌芽发生。万物其所赋与，洪纤髙下，各正其性命，无有差妄，物与无妄也。先王观天下雷行发生，赋与之象，而以茂对天时，养育万物，使各得其宜，如天与之无妄也。茂盛也，“茂对”之为言，犹“盛行”永言之比。对时谓顺合天时，天道生万物，各正其性命而不妄。王者体天之道，养育人民以至昆虫草木，使各得其宜，乃对时育物之道也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>九家易曰 ：天下雷行，阳气普遍，无物不与，故曰物与也。</p></li><li><p>朱子语类 问：“物与无妄”众说不同。文蔚曰：是各正性命之意。 答：然，一物与他一个无妄。</p></li><li><p>问：“物与无妄”众说不同。文蔚曰：是各正性命之意。 答：然，一物与他一个无妄。</p></li><li><p>俞氏琰曰 ：天有是时，先王非能先后之也，对而循之耳；物有是生，先王非能损益之也，育而成之耳。中庸之所谓诚，即易之所谓无妄也。中庸云：“唯天下至诚为能尽其性，能尽其性则能尽人之性，能尽人之性则能尽物之性，能尽物之性则可以赞天地之化育，可以赞天地之化育则可以与天地参矣。”子思之说，盖本于此。</p></li><li><p>蔡氏清曰 ：物与无妄者，万物各正其性命也；对时育物者，因其所性而不为私，乃圣人尽物之性也。</p></li></ul><p>彖曰：无妄，刚自外来而为主于内，动而健，刚中而应，大亨以正，天之命也。其匪正有眚，不利有攸往。无妄之往，何之矣？天命不祐，行矣哉！</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦变、卦德、卦体言，卦之善如此，故其占当获大亨而利于正，乃天命之当然也。其有不正则不利有所往，欲何往哉？盖其逆天之命而天不祐之，故不可以有行也。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>谓初九也。坤初爻变而为震，刚自外而来也。震以初爻为主，成卦由此，故初为无妄之主。动以天为无妄，动而以天动为主也。以刚变柔，为以正去妄之象，又刚正为主于内，无妄之义也。九居初正也，下动而上健，是其动刚健也。刚健无妄之体也，刚中而应五，以刚居中正，二复以中正相应，是顺理而不妄也。故其道大亨通而贞正，乃天之命也。天命谓天道也，所谓无妄也。所谓无妄，正而已。小失于正，则为有过，乃妄也。所谓匪正，盖由有往。若无妄而不往，何由有匪正乎？无妄者，理之正也。更有往，将何之矣？乃入于妄也。往则悖于天理，天道所不佑，可行乎哉？</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏宗传曰：初九之刚，干一索于坤而得之，是以为震而无妄之外体，又干也，则初九之刚实自干来，故曰“刚自外来”。震以初爻为主，其在无妄则内体也，故曰“为主于内”。</p></li><li><p>赵氏彦肃曰：刚自外来，寄象尔，其实天之所赋，我固有也。</p></li><li><p>胡氏炳文曰：外卦为干，震之刚自干来也。无妄释元亨利贞与临同，命即道也。无妄之往，程子以为无妄而又往，本义只顺上文本意解，举首尾句而包中间也，不可泥文而失意。</p></li><li><p>何氏楷曰：震初一刚，其所从来即干之初画。无妄外干内震，初九得外卦乾刚初爻以为内卦之主，故曰“刚自外来而为主于内”。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>彖言“刚来柔来”，未有言“自外来者”，则王氏诸家谓指外卦干体者信矣。在卦为震，得干最初之画；在人为吾心，得天最初之理。此所以为无妄也。天理非由外铄，我者此特指卦象言之，见自干来之意。赵氏之说是矣。</p><p>初九：无妄往吉。</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以刚在内，诚之主也。如是而往，其吉可知，故其象占如此。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>九以阳刚为主于内，无妄之象。以刚实变柔而居内，中诚不妄者也。以无妄而往，何所不吉？卦辞言“不利有攸往”，谓既无妄不可复有往也，过则妄矣。爻言“往吉”，谓以无妄之道而行，则吉也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>兰氏廷瑞曰：初则当行，终则当止。行止适当，则无妄。不妄则吉。无妄之初，当行者也，故往则有吉。无妄之终，当止者也，故行则有眚。</p></li><li><p>胡氏炳文曰：彖曰：“刚自外来而为主于内。”本义于此曰“以刚在内，诚之主也”。主字最有力。盖妄者诚之反也，诚之主如此，妄自然无矣。如此而往，其吉固宜。</p></li><li><p>何氏楷曰：此爻足蔽无妄全卦。震阳初动，诚一未分，是之谓无妄。以此而往，动与天合，何不吉之有？</p></li></ul><p>象曰：无妄之往，得志也</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>以无妄而往，无不得其志也。盖诚之于物，无不能动。以之脩身，则身正；以之治事，则事得其理；以之临人，则人感而化，无所往而不得其志也。</p><p>六二：不耕获，不菑畬，则利有攸往。</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>柔顺中正，因时顺理而无私意期望之心，故有不耕获、不菑畬之象。言其无所为于前，无所兾于后也。占者如是，则利有所往也。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>凡理之所然者，非妄也；人所欲为者，乃妄也。故以耕获、菑畬譬之。六二居中得正，又应五之中正，居动体而柔顺为动，能顺乎中正，乃无妄者也。故极言无妄之义。耕农之始获其成终也，田一岁曰菑，三岁曰畬。不耕而获，不菑而畬，谓不首造其事，因其事理所当然也。首造其事，则是人心所作为，乃妄也；因事之当然，则是顺理应物，非妄也。获与畬是也。盖耕则必有获，菑则必有畬，是事理之固然，非心意之所造作也。如是则为无妄，不妄则所往利而无害也。或曰：“圣人制作以利天下者，皆造端也，岂非妄乎？”曰：“圣人随时制作，合乎风气之宜，未尝先时而开之也。若不待时，则一圣人足以尽为矣，岂待累圣继作也？时乃事之端，圣人随时而为也。”</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类 ：问：《程传》爻辞恐未明白，窃谓无不耕而获、不菑而畬之理，只是不于耕而计获之利。如程子所解，象传移之以解爻辞则可。 曰：《易传》爻象之辞，虽若相反，而意实相近，特辞有未足耳。爻辞言当循理，《象传》言不计利。</p></li><li><p>问：《程传》爻辞恐未明白，窃谓无不耕而获、不菑而畬之理，只是不于耕而计获之利。如程子所解，象传移之以解爻辞则可。 曰：《易传》爻象之辞，虽若相反，而意实相近，特辞有未足耳。爻辞言当循理，《象传》言不计利。</p></li><li><p>陈氏埴曰 ：伊川大意只谓不为获而耕，不为畬而菑。凡有所为而为者，皆计利之私心，即妄也。但经文中不如此下语，故易传中颇费言语。始谓不耕而获、不菑而畬，谓不首造其事，则似以耕菑为私意；中谓耕则必有获、菑则必有畬，非心造意作，则以耕获、菑畬为非私意；终谓既耕则必有获、既菑则必成畬，非必以获畬之富而为，则又似以获畬为私意。三说不免自相抵捂，所以本义但据经文直说，谓无耕获、菑畬之私心。</p></li><li><p>胡氏炳文曰 ：耕获者，种而敛之也；菑畬者，垦而熟之也。一岁之农始于耕终于获，三岁之田始于菑终于畬。不耕获、不菑畬，诸家以为不耕而获、不菑而畬，惟本义以为始终无所作为之象。而必曰因时顺理者，理本自然，无所作为，自始至终，绝无计功谋利之心。故其占曰：“利有攸往。”</p></li><li><p>林氏希元曰 ：田必耕然后获，必菑然后畬。其耕也，正以望获；其菑也，正以望畬。岂有不耕获、不菑畬之理？为此语者，特以明自始至终，绝无营为计较之心焉耳。</p></li><li><p>何氏楷曰 ：人之有妄，在于期望。不耕获者，不方耕而即望有其获也；不菑畬者，不方菑而即望成其畬也。学者之除妄心而必有事焉，当如此矣。故曰“则利有攸往”，言必如此而后利也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>何氏说与传义颇异，质诸夫子“先事后得”、“先难后获”之训，则于理尤长。且象传以“未富”释之，正谓其无望获之心，未必以耕为可废也。</p><p>象曰：不耕获，未富也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>富，如非富天下之富，言非计其利而为之也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>未者，非必之辞（临卦曰“未顺命”是也）。不耕而获，不菑而畬，因其事之当然。既耕则必有获，既菑则必成畬，非必以获畬之富而为也。其始耕菑，乃设心在于求获畬，是以其富也。心有欲而为者，则妄也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>丰氏寅初曰 ：未犹非也。富谓利也，不于力耕之际遽有望获之心，乃仁人不计功谋利而天德全矣。其行之所以利也。</li></ul><p>六三：无妄之灾，或系之牛，行人之得，邑人之灾。</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>卦之六爻皆无妄者也，六三处不得正，故遇其占者无故而有灾。如行人牵牛以去，而居者反遭诘捕之扰也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>三以阴柔而不中正，是为妄者也。又志应于上，欲也，亦妄也。在无妄之道，为灾害也。人之妄动由有欲也，妄动而得亦必有失。虽使得其所利，其动而妄，失已大矣。况复凶悔随之乎？知者见妄之得，则知其失必与称也。故圣人因六三有妄之象而发明其理，云“无妄之灾，或系之牛，行人之得，邑人之灾”。言如三之为妄，乃无妄之灾害也。设如有得，其失随至。如或系之牛，或谓设或也，或系得牛，行人得之以为有得，邑人失牛，乃是灾也。借使邑人系得马，则行人失马，乃是灾也。言有得则有失，不足以为得也。行人邑人但言有得则有失，非以为彼已也。妄得之福，灾亦随之。妄得之得，失亦称之，固不足以为得也。人能知此，则不为妄动矣。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>关氏朗曰 ：无妄而灾者，灾也。有妄而灾，则其所也，非灾之也。运数适然，非己妄致，乃无妄之灾。</p></li><li><p>朱子语类云 ：此卦六爻皆是无妄，但六三地头不正，故有无妄之灾。言无故而有灾也，如行人牵牛以去，而居人反遭捕诘之扰，此正无妄之灾之象。</p></li><li><p>胡氏炳文曰 ：匪正有眚，人自为之也；无妄之灾，天实为之也。六爻皆无妄，三之时则无妄而有灾者也。《杂卦》曰：“无妄灾也。”其此之谓与。</p></li></ul><p>象曰：行人得牛，邑人灾也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>行人得牛，乃邑人之灾也。有得则有失，何足以为得乎？</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>丰氏寅初曰 ：邑人之灾，所谓无妄之灾。然无故被诬者，反己无怍，君子求其无妄而已，祸福听之于天，悉置度外也。</li></ul><p>九四：可贞无咎。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>阳刚干体，下无应与，可固守而无咎，不可以有为之占也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>四刚阳而居干体，复无应与，无妄者也。刚而无私，岂有妄乎？可贞固守此，自无咎也。九居阴得为正乎？曰以阳居干体，若复处刚则为过矣，过则妄也。居四无尚刚之志也，可贞与利贞不同。可贞谓其所处可贞固守之，利贞谓利于贞也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏炳文曰 ：贞，正而固也。曰“利贞”，则训“正”字而兼“固”字之义；曰“不可贞”，则专训“固”字而无“正”字之义。九四阳刚健体，下无应与，可贞正守之，而其占不可有为也。</p></li><li><p>何氏楷曰 ：四刚阳而居干体，本自无妄者也。可贞固守此，则无咎。初九之“无妄往吉”，行乎其所当行者也；九四之“可贞无咎”，止乎其所当止者也。</p></li></ul><p>象曰：可贞无咎，固有之也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>有，犹守也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>贞，固守之则无咎也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰 ：固有之者，生而性之，非外掠而取之也。</p></li><li><p>王氏宗传曰 ：正者人之性也，非外铄我者，我固有之也。因其固有而不失之，故曰“可贞无咎”。</p></li></ul><p>九五：无妄之疾，勿药有喜。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>乾刚中正，以居尊位，而下应亦中正，无妄之至也。如是而有疾，勿药而自愈矣，故其象占如此。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>九以中正当尊位，下复以中正顺应之，可谓无妄之至者也。其道无以加矣。疾，为之病者也。以九五之无妄，如其有疾，勿以药治，则有喜也。人之有疾，则以药石攻去其邪，以养其正。若气体平和，本无疾病，而攻治之，则反害其正矣。故勿药，则有喜也。有喜，谓疾自亡也。无妄之所谓疾者，谓若治之而不治，率之而不从，化之而不革，以妄而为无妄之疾。舜之有苖，周公之管蔡，孔子之叔孙武叔是也。既已无妄，而有疾之者，则当自如无妄之疾，不足患也。若遂自攻治，乃是渝其无妄而迁于妄也。五既处无妄之极，故惟戒在动，动则妄矣。</p><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>勿者，禁止之辞。言无妄矣而偶有疾，则亦顺其自然而气自复，勿复用药以生他候。如人有无妄之灾，则亦顺其自然而事自平，勿复用智以生他咎也。凡《易》中言“勿”者，皆同义。此爻之疾与六三之灾同然，此曰“有喜”者，刚中正而居尊位，德位固不同也。</p><p>象曰：无妄之药，不可试也</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>既已无妄，而复药之，则反为妄而生疾矣。试，谓少尝之也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>人之有妄，理必脩改。既无妄矣，复药以治之，是反为妄也，其可用乎？故云“不可试也”。试，暂用也，犹曰少尝之也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>林氏希元曰 ：既无妄而复药，则为以无妄之疾试无妄之药，反为妄而生疾矣。然则所处既当于理，岂可因非意之事而改图乎？</p></li><li><p>钱氏志立曰 ：九五阳刚中正，本无致疾之道，而有疾焉，此无妄之疾也。惟守正安常以处之，疾且自去。而试之药焉，则必以吾之常者为非，而悉反其道，斯纷纷召疾之方至矣。故曰“无妄之药不可试也”。</p></li></ul><p>上九：无妄行，有眚，无攸利。</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>上九非有妄也，但以其穷极而不可行耳，故其象占如此。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>上九居卦之终，无妄之极者也。极而复行，过于理也。过于理，则妄也。故上九而行，则有过眚而无所利矣。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>龚氏焕曰 ：无妄者，实理自然之谓。循是理则吉，拂是理则凶。初“往吉”，二“利有攸往”，循是理而动者也；四“可贞无咎”，守是理而不动者也；三有灾，五有疾，不幸而遇无故非意之事，君子亦听之而已，守是理而不为动者也。或动或静，惟理是循，所以为无妄。上九居无妄之极，不可有行。若不循理而动，则反为妄矣。其有眚而不利也，宜哉。</p></li><li><p>何氏楷曰 ：彖所谓“匪正有眚，不利有攸往”者，正指此爻而言。</p></li></ul><p>象曰：无妄之行，穷之灾也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>无妄既极而复加进，乃为妄矣。是穷极而为灾害也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>赵氏玉泉曰 ：无妄之行宜无灾矣，但处时之穷，则有其德而无其时，故有灾也。</p></li><li><p>何氏楷曰 ：无妄之行，犹彖传所云“无妄之往”。上九干之穷与干亢龙义同，故二小象亦同。以其意于行，故曰“眚”；以其时位使然，故曰“灾”。</p></li></ul><p>总论</p><ul><li>胡氏炳文曰 ：六爻皆无妄也。特初九得位而为震动之主，时之方来，故“无妄往吉”；上九失位而居干体之极，时已去矣，故其行虽无妄，有眚无攸利。是故善学《易》者，在识时。初曰吉，二曰利，时也；三曰灾，五曰疾，上曰眚，非有妄以致之也，亦时也。初与二皆可往，时当动而动也；四可贞，五勿药，上“行有眚”，时当静而静也。</li></ul>',106)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
